package com.bank.audit;

import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.logging.*;

public class PeekPitfallDemo {
    private static final Logger log = Logger.getLogger("Peek");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> txns = List.of("TXN1", "TXN2", "TXN3");

        // BUG: side-effect in peek, terminal is count() → peek may be skipped (Java 9+)
        AtomicInteger buggyAudited = new AtomicInteger();
        long n = txns.stream().peek(t -> buggyAudited.incrementAndGet()).count();
        log.warning(() -> "count=" + n + " but audited via peek=" + buggyAudited.get()
            + " (may be 0 — peek skipped!)");

        // FIX: use forEach, which is guaranteed to run for every element
        AtomicInteger safeAudited = new AtomicInteger();
        txns.forEach(t -> safeAudited.incrementAndGet());
        log.info(() -> "audited via forEach=" + safeAudited.get() + " (always correct)");
    }
}
